 * @param {string} from
 * @param {string} to
 * @returns {boolean}
 */
function canTransition(from, to) {
  if (!Object.hasOwn(ALLOWED_TRANSITIONS, from)) return false;
  return ALLOWED_TRANSITIONS[/** @type {OrderStatus} */ (from)].includes(
    /** @type {OrderStatus} */ (to),
  );
}

