// @ts-check
// Fails fast with a useful message when the test database is missing or out
// of date. It only checks; creating and migrating is `npm run db:test:setup`.

const fs = require('node:fs');
const path = require('node:path');
const { Sequelize } = require('sequelize');
const config = require('../../src/schema/config');

const MIGRATIONS_DIR = path.resolve(__dirname, '../../src/schema/migrations');
const HINT = 'Run `npm run db:test:setup` (with `docker compose up -d`) first.';

module.exports = async function globalSetup() {
  const { url, ...options } = config.test;
  const sequelize = new Sequelize(url, options);
  try {
    const [rows] = await sequelize.query('SELECT name FROM "SequelizeMeta"');
    const applied = new Set(/** @type {Array<{ name: string }>} */ (rows).map((row) => row.name));
    const pending = fs.readdirSync(MIGRATIONS_DIR).filter((file) => !applied.has(file));
    if (pending.length > 0) {
      throw new Error(`Test database has pending migrations: ${pending.join(', ')}. ${HINT}`);
    }
  } catch (error) {
    const reason = error instanceof Error ? error.message : String(error);
    throw new Error(`Integration test database is not ready (${reason}). ${HINT}`);
  } finally {
    await sequelize.close();
  }
};
EOF
cat > test/integration/helpers/db.js <<'EOF'
// @ts-check
// Helpers shared by integration tests: reset tables between tests and insert
// small fixtures. Tests never use the demo seed.

const { sequelize, MenuItem, Order, OrderItem } = require('../../../src/schema/models');

const TABLES = 'order_items, orders, menu_items';

/** Guard so a misconfigured env can never truncate the dev database. */
function assertTestDatabase() {
  const name = sequelize.getDatabaseName();
  if (!name.endsWith('_test')) {
    throw new Error(`Refusing to reset non-test database "${name}"`);
  }
}

async function resetDb() {
  assertTestDatabase();
  await sequelize.query(`TRUNCATE ${TABLES} RESTART IDENTITY CASCADE`);
}

async function closeDb() {
  await sequelize.close();
}

/**
 * @param {Partial<{ name: string, category: string, prep_time_minutes: number }>} [overrides]
 */
async function createMenuItem(overrides = {}) {
  return MenuItem.create({
    name: `Item ${Math.random().toString(36).slice(2, 8)}`,
    category: 'main_course',
    prep_time_minutes: 10,
    ...overrides,
  });
}

/**
 * Creates an order and its items in one go.
 * @param {Record<string, unknown>} [overrides] Order columns.
 * @param {Array<{ menu_item_id: number, quantity: number }>} [items]
 */
async function createOrder(overrides = {}, items = []) {
  const order = await Order.create({
    customer_name: 'Test Customer',
    type: 'dine_in',
    is_vip: false,
    status: 'received',
    placed_at: new Date('2026-06-15T11:30:00Z'),
    promised_at: null,
    ...overrides,
  });
  for (const item of items) {
    await OrderItem.create({ ...item, order_id: order.get('id') });
  }
  return order;
}

module.exports = { sequelize, resetDb, closeDb, createMenuItem, createOrder };
EOF
cat > test/integration/schema.test.js <<'EOF'
// Proves the integration setup works against real Postgres and that the
// migrations enforce the data model rules (not just the app code).

const { Order, OrderItem } = require('../../src/schema/models');
const { resetDb, closeDb, createMenuItem, createOrder } = require('./helpers/db');

beforeEach(resetDb);
afterAll(closeDb);

describe('schema constraints', () => {
  test('an order with items can be stored and read back with its menu items', async () => {
    const salmon = await createMenuItem({ name: 'Grilled Salmon', prep_time_minutes: 20 });
    const order = await createOrder({}, [{ menu_item_id: salmon.get('id'), quantity: 2 }]);

    const loaded = await Order.findByPk(order.get('id'), {
      include: [{ association: 'items', include: ['menu_item'] }],
    });
    const plain = loaded.get({ plain: true });
    expect(plain.items).toHaveLength(1);
    expect(plain.items[0].quantity).toBe(2);
    expect(plain.items[0].menu_item.name).toBe('Grilled Salmon');
  });

  test('timestamps round-trip in UTC', async () => {
    const placedAt = new Date('2026-06-15T11:25:00Z');
    const order = await createOrder({ placed_at: placedAt });
    const loaded = await Order.findByPk(order.get('id'));
    expect(loaded.get('placed_at').toISOString()).toBe('2026-06-15T11:25:00.000Z');
  });

  test.each([
    ['blank customer_name', { customer_name: '   ' }],
    ['unknown type', { type: 'drive_thru' }],
    ['unknown status', { status: 'done' }],
  ])('rejects %s', async (_label, overrides) => {
    await expect(createOrder(overrides)).rejects.toThrow(/check constraint/);
  });

  test('rejects quantity 0', async () => {
    const item = await createMenuItem();
    await expect(createOrder({}, [{ menu_item_id: item.get('id'), quantity: 0 }])).rejects.toThrow(
      /order_items_quantity_positive/,
    );
  });

  test('rejects an order item for a missing menu item', async () => {
    await expect(createOrder({}, [{ menu_item_id: 999, quantity: 1 }])).rejects.toThrow(
      /foreign key/,
    );
  });

  test('deleting an order deletes its items', async () => {
    const item = await createMenuItem();
    const order = await createOrder({}, [{ menu_item_id: item.get('id'), quantity: 1 }]);
    await order.destroy();
    expect(await OrderItem.count()).toBe(0);
  });
});
EOF
