 * @property {boolean} is_vip
 * @property {import('../modules/transitions').OrderStatus} status
 * @property {Date} placed_at
 * @property {Date | null} promised_at
 * @property {OrderItemRecord[]} items
 */

const WITH_ITEMS = {
  include: [
    {
      model: OrderItem,
      as: 'items',
      include: [{ model: MenuItem, as: 'menu_item' }],
    },
  ],
