  { value: 'received', label: 'Received' },
  { value: 'preparing', label: 'Preparing' },
];

interface Props {
  value: QueueFilter;
  onChange: (value: QueueFilter) => void;
}

export function QueueFilterToggle({ value, onChange }: Props) {
  return (
    <ToggleButtonGroup
      size="small"
      exclusive
      value={value}
      // Clicking the selected option passes null; keep the current filter.
      onChange={(_event, next: QueueFilter | null) => next && onChange(next)}
      aria-label="Queue filter"
    >
      {OPTIONS.map((option) => (
        <ToggleButton key={option.value} value={option.value} sx={{ px: 1.5, py: 0.25 }}>
          {option.label}
        </ToggleButton>
      ))}
    </ToggleButtonGroup>
  );
}
  const [filter, setFilter] = useState<QueueFilter>('active');
  const { orders, loading, error, pendingOrderId, reload, runAction, clearError } = useQueue(filter);

  return (
    <Box component="main" sx={{ p: 2 }}>
      <Stack direction="row" spacing={2} sx={{ mb: 1.5, alignItems: 'center' }}>
        <Typography variant="h6" component="h1" sx={{ flexGrow: 1 }}>
          Kitchen Display
        </Typography>
        <QueueFilterToggle
          value={filter}
          onChange={(next) => {
            // An error from the previous view no longer applies.
            clearError();
            setFilter(next);
          }}
        />
        <Button size="small" variant="outlined" onClick={() => void reload()} disabled={loading}>
          Refresh
        </Button>
      </Stack>

      {error && (
        <Alert severity="error" onClose={clearError} sx={{ mb: 1.5 }} role="alert">
          <strong>{error.code}</strong>: {error.message}
        </Alert>
      )}

      <Paper variant="outlined">
        <Box sx={{ height: 4 }}>{loading && <LinearProgress />}</Box>
        <QueueTable
          orders={orders}
          pendingOrderId={pendingOrderId}
          onAction={(orderId, action) => void runAction(orderId, action)}
        />
      </Paper>
    </Box>
  );
}

